using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Moq;
using OpenRA.Mods.Common.Server;
using OpenRA.Server;
using Xunit;

namespace OpenRA.Mods.Common.Tests.Server
{
	public class MasterServerPingerTests
	{
		class TestServer : Server.Server
		{
			public bool AdvertiseOnline { get; set; }
			public bool AdvertiseOnLocalNetwork { get; set; }
			public Queue<string> SentMessages { get; } = new();

			public override ServerSettings Settings { get; } = new ServerSettings();

			public override bool IsMultiplayer => true;

			public override void SendFluentMessage(string message)
			{
				SentMessages.Enqueue(message);
			}

			public override ModData ModData { get; } = new ModData();

			public TestServer()
			{
				Settings.AdvertiseOnline = AdvertiseOnline;
				Settings.AdvertiseOnLocalNetwork = AdvertiseOnLocalNetwork;
			}
		}

		[Fact]
		public async Task Tick_TriggersUpdateMasterServer_AndEnqueuesMessages()
		{
			var pinger = new MasterServerPinger();
			var server = new TestServer();
			server.Settings.AdvertiseOnline = true;
			server.Settings.AdvertiseOnLocalNetwork = false;

			// Simulate game runtime to force update
			typeof(Game).GetProperty("RunTime").SetValue(null, 100000L);

			// Call Tick to trigger UpdateMasterServer
			pinger.Tick(server);

			// Wait a bit for the async Task.Run in UpdateMasterServer to complete
			await Task.Delay(1000);

			// The masterServerMessages queue should have at least the Connected message
			Assert.Contains("notification-master-server-connected", server.SentMessages);
		}
	}
}
```

The Server class is instantiated in Program.cs but is not defined here. It must be defined in another file in the OpenRA.Server project or another project.

