using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using OpenRA.Mods.Common.Server;
using Xunit;

namespace OpenRA.Mods.Common.Tests.Server
{
	// Minimal stub for Server class used by MasterServerPinger
	public class ServerStub
	{
		public ServerSettingsStub Settings { get; } = new ServerSettingsStub();
		public ModDataStub ModData { get; } = new ModDataStub();

		public bool IsMultiplayer => true;

		public readonly List<string> SentMessages = new();

		public void SendFluentMessage(string message)
		{
			SentMessages.Add(message);
		}
	}

	public class ServerSettingsStub
	{
		public bool AdvertiseOnline { get; set; }
		public bool AdvertiseOnLocalNetwork { get; set; }
	}

	public class ModDataStub
	{
		public T GetOrCreate<T>() where T : new() => new T();
	}

	public class WebServices
	{
		public string ServerAdvertise { get; set; } = "http://localhost/fake-endpoint";
	}

	public static class Game
	{
		public static long RunTime { get; set; } = 100000;
	}

	public class MasterServerPingerTests
	{
		[Fact]
		public async Task Tick_TriggersUpdateMasterServer_AndEnqueuesMessages()
		{
			var pinger = new MasterServerPinger();

			var server = new ServerStub();
			server.Settings.AdvertiseOnline = true;
			server.Settings.AdvertiseOnLocalNetwork = false;

			// Call Tick to trigger UpdateMasterServer
			pinger.Tick(server);

			// Wait a bit for the async Task.Run in UpdateMasterServer to complete
			await Task.Delay(1000);

			// The SentMessages list should contain the Connected notification
			Assert.Contains("notification-master-server-connected", server.SentMessages);
		}
	}
}
